logger = logging.getLogger(__name__)

PricingRates = dict[str, int]
PricingTierMap = dict[str, PricingRates]
PricingMap = dict[str, PricingTierMap]

# Fallback for unknown models — Opus 4 rates (most expensive known model).
# Using a high fallback means unknown models are over-counted rather than
# under-counted, which protects budget limits.
_FALLBACK_RATES: PricingRates = {
    "input_usd_micros_per_1k": 15_000,
    "output_usd_micros_per_1k": 75_000,
    "cache_read_input_usd_micros_per_1k": 75_000,
    "cache_write_input_usd_micros_per_1k": 75_000,
}

# Live-catalog cache. A successful read or an authoritative absence is cached for
# _PRICING_TTL; a transient/corrupt S3 condition falls back to DEFAULT_PRICING but is
# cached only for _PRICING_RETRY_TTL so a subsequent successful refresh is picked up
# promptly. _PRICING_CACHE_TTL holds the TTL the current cache entry was written with.
_PRICING_CACHE: PricingMap | None = None
_PRICING_CACHE_AT: float = float("-inf")
_PRICING_CACHE_TTL: float = 0.0
_PRICING_TTL: float = float(os.environ.get("PRICING_CACHE_TTL_S", "60"))
_PRICING_RETRY_TTL: float = 5.0


def _rate(value: object) -> int:
    """A catalog rate: a non-negative int. Anything else (bool, float, str, negative) is unusable."""
    if type(value) is not int or value < 0:
        raise ValueError(f"invalid rate {value!r}")
    return value


def _normalize_rates(rates: object) -> PricingRates | None:
    """Return int rates with cache rates defaulted to output, or None if the tier is unusable.

    Unusable means not a dict, missing input/output, or any rate that isn't a non-negative
    int — a negative rate would credit budgets back. The caller replaces or drops one bad
    tier on its own.
    """
    if not isinstance(rates, dict):
        return None
    try:
        input_rate = _rate(rates["input_usd_micros_per_1k"])
        output_rate = _rate(rates["output_usd_micros_per_1k"])
        return {
            "input_usd_micros_per_1k": input_rate,
            "output_usd_micros_per_1k": output_rate,
            "cache_read_input_usd_micros_per_1k": _rate(
                rates.get("cache_read_input_usd_micros_per_1k", output_rate)
            ),
            "cache_write_input_usd_micros_per_1k": _rate(
                rates.get("cache_write_input_usd_micros_per_1k", output_rate)
            ),
        }
    except (KeyError, ValueError):
        return None


def _normalize_pricing_map(raw_map: dict, fallback: PricingMap | None = None) -> PricingMap:
    """Keep each service tier that normalizes; drop a model whose Standard tier does not and
    cannot be replaced from *fallback*.

    A present-but-invalid tier is logged and, when *fallback* (the normalized baked-in
    DEFAULT_PRICING) holds that model and tier, replaced by the baked-in rate — closer to
    the truth than billing Standard (a bad Priority tier) or the Opus-tier fallback (a bad
    Standard tier).
    """
    fallback = fallback or {}
    normalized: PricingMap = {}
    for model_id, value in raw_map.items():
        if not isinstance(value, dict):
            # Treat Standard, and each tier the baked-in catalog has, as present-but-invalid:
            # each is logged and replaced from *fallback*, or the model is dropped.
            value = dict.fromkeys({"standard", *fallback.get(model_id, {})})
        tiers: PricingTierMap = {}
        for tier in SERVICE_TIERS:
            rates = _normalize_rates(value[tier]) if tier in value else None
            if rates is None and (tier in value or tier == "standard"):  # absent Flex is normal
                logger.warning(
                    json.dumps(
                        {"event": "pricing_entry_invalid", "model_id": model_id, "tier": tier}
                    )
                )
                rates = fallback.get(model_id, {}).get(tier)
            if rates is not None:
                tiers[tier] = rates
        if "standard" in tiers:
            normalized[model_id] = tiers
    return normalized


@functools.cache
def _default_pricing() -> PricingMap:
    """DEFAULT_PRICING, normalized once per process."""
    return _normalize_pricing_map(DEFAULT_PRICING)


def _load_pricing() -> PricingMap:
    """Return the normalized pricing map: the live S3 catalog, else DEFAULT_PRICING.

    Per-instance TTL cache (see the cache globals). The live catalog is the single
    runtime source; DEFAULT_PRICING is the bootstrap/availability fallback.
    """
    global _PRICING_CACHE, _PRICING_CACHE_AT, _PRICING_CACHE_TTL
    if _PRICING_CACHE is not None and time.monotonic() - _PRICING_CACHE_AT < _PRICING_CACHE_TTL:
        return _PRICING_CACHE
    try:
        live = load_live_catalog(get_s3())
        if live is None:
            _PRICING_CACHE = _default_pricing()
        else:
            normalized = _normalize_pricing_map(live, _default_pricing())
            if not normalized:
                raise ValueError("live catalog has no valid entries")
            _PRICING_CACHE = normalized
        ttl = _PRICING_TTL
    except Exception as exc:
        # Transient S3, or a corrupt object (unparseable, not a catalog, or no valid entry)
        # — serve baked-in rates, but re-check soon. A single malformed tier is instead
        # replaced from DEFAULT_PRICING in _normalize_pricing_map.
        logger.warning(json.dumps({"event": "pricing_source_unavailable", "error": str(exc)}))
        _PRICING_CACHE = _default_pricing()
        ttl = _PRICING_RETRY_TTL
    _PRICING_CACHE_AT = time.monotonic()
    _PRICING_CACHE_TTL = ttl
    return _PRICING_CACHE


def invalidate_cache() -> None:
    """Force the next _load_pricing() to re-read the live catalog (post-refresh)."""
    global _PRICING_CACHE_AT
    _PRICING_CACHE_AT = float("-inf")


def _resolve_rates(model_id: str, service_tier: str) -> tuple[PricingRates, bool, list[str]]:
    """Return (rates, fallback_applied, fallback_dimensions) for a model at a service tier.

    An unknown model bills _FALLBACK_RATES at any tier. A known model without a rate for
    the tier (incl. commitment-priced "reserved") bills that model's Standard rate.
    """
    model = _load_pricing().get(model_id)
    if model is None:
        rates, dimension = _FALLBACK_RATES, "model_id"
    elif service_tier in model:
        return dict(model[service_tier]), False, []
    else:
        rates, dimension = model["standard"], "service_tier"
    logger.warning(
        json.dumps(
            {
                "event": "pricing_fallback_rate",
                "model_id": model_id,
                "service_tier": service_tier,
                "dimension": dimension,
            }
        )
    )
    return dict(rates), True, [dimension]


def compute_cost(
    model_id: str,
    service_tier: str,
    input_tokens: int,
    output_tokens: int,
    cache_read_input_tokens: int,
    cache_write_input_tokens: int,
) -> tuple[int, dict[str, int], bool, list[str], PricingRates]:
    """Return (total_cost, component_costs, fallback_applied, fallback_dimensions, rates)."""
    rates, fallback_applied, fallback_dimensions = _resolve_rates(model_id, service_tier)
    components = {
        "input_usd_micros": (input_tokens * rates["input_usd_micros_per_1k"]) // 1000,
        "output_usd_micros": (output_tokens * rates["output_usd_micros_per_1k"]) // 1000,
        "cache_read_input_usd_micros": (
            cache_read_input_tokens * rates["cache_read_input_usd_micros_per_1k"]
        )
        // 1000,
        "cache_write_input_usd_micros": (
            cache_write_input_tokens * rates["cache_write_input_usd_micros_per_1k"]
        )
        // 1000,
    }
    return sum(components.values()), components, fallback_applied, fallback_dimensions, rates
